export { useRovingFocus } from './useRovingFocus';
export type {
  UseRovingFocusOptions,
  UseRovingFocusReturn,
} from './useRovingFocus.types';

import { useCallback, useState, type KeyboardEvent } from 'react';

import type {
  UseRovingFocusOptions,
  UseRovingFocusReturn,
} from './useRovingFocus.types';

/**
 * Manages roving tabindex focus within a container of interactive items.
 *
 * Implements the WAI-ARIA roving tabindex pattern: only the currently focused
 * item has `tabindex="0"`, all others have `tabindex="-1"`. Supports vertical,
 * horizontal, and both orientations with optional wrapping and Home/End keys.
 *
 * @param options - Configuration for the roving focus behavior.
 * @returns An object containing container props, the focused index, and a setter.
 *
 * @example
 * ```tsx
 * function Listbox() {
 *   const ref = useRef<HTMLUListElement>(null);
 *   const { containerProps } = useRovingFocus({
 *     containerRef: ref,
 *     itemSelector: '[role="option"]',
 *   });
 *
 *   return (
 *     <ul ref={ref} role="listbox" {...containerProps}>
 *       <li role="option" tabIndex={0}>Item 1</li>
 *       <li role="option" tabIndex={-1}>Item 2</li>
 *     </ul>
 *   );
 * }
 * ```
 */
export function useRovingFocus({
  containerRef,
  orientation = 'vertical',
  wrap = true,
  homeEnd = true,
  itemSelector = '[role="option"]',
  disabledSelector = '[aria-disabled="true"]',
  enabled = true,
}: UseRovingFocusOptions): UseRovingFocusReturn {
  const [focusedIndex, setFocusedIndexState] = useState(0);

  const getFocusableItems = useCallback((): HTMLElement[] => {
    if (!containerRef.current) {
      return [];
    }
    try {
      return Array.from(
        containerRef.current.querySelectorAll<HTMLElement>(itemSelector),
      );
    } catch {
      return [];
    }
  }, [containerRef, itemSelector]);

  const isDisabled = useCallback(
    (el: HTMLElement): boolean => {
      if (!disabledSelector) {
        return false;
      }
      try {
        return el.matches(disabledSelector);
      } catch {
        return false;
      }
    },
    [disabledSelector],
  );

  const focusItem = useCallback(
    (items: HTMLElement[], index: number) => {
      const item = items[index] as HTMLElement | undefined;
      if (!item) {
        return;
      }

      // Update tabIndex on all items
      for (const el of items) {
        el.setAttribute('tabindex', '-1');
      }
      item.setAttribute('tabindex', '0');
      item.focus();

      setFocusedIndexState(index);
    },
    [setFocusedIndexState],
  );

  const findNextIndex = useCallback(
    (items: HTMLElement[], current: number, direction: 1 | -1): number => {
      const len = items.length;
      let next = current + direction;

      for (let i = 0; i < len; i++) {
        if (wrap) {
          next = ((next % len) + len) % len;
        } else if (next < 0 || next >= len) {
          return current;
        }

        const item = items[next] as HTMLElement | undefined;
        if (item && !isDisabled(item)) {
          return next;
        }
        next += direction;
      }

      return current;
    },
    [wrap, isDisabled],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      if (!enabled || typeof document === 'undefined') {
        return;
      }

      const items = getFocusableItems();
      if (items.length === 0) {
        return;
      }

      // Find current focused index from DOM
      const currentIndex = items.findIndex(
        (el) =>
          el === document.activeElement ||
          el.contains(document.activeElement),
      );
      if (currentIndex === -1) {
        return;
      }

      let prevKeys: string[];
      let nextKeys: string[];

      if (orientation === 'both') {
        prevKeys = ['ArrowUp', 'ArrowLeft'];
        nextKeys = ['ArrowDown', 'ArrowRight'];
      } else if (orientation === 'horizontal') {
        prevKeys = ['ArrowLeft'];
        nextKeys = ['ArrowRight'];
      } else {
        prevKeys = ['ArrowUp'];
        nextKeys = ['ArrowDown'];
      }

      if (nextKeys.includes(event.key)) {
        event.preventDefault();
        const next = findNextIndex(items, currentIndex, 1);
        focusItem(items, next);
      } else if (prevKeys.includes(event.key)) {
        event.preventDefault();
        const next = findNextIndex(items, currentIndex, -1);
        focusItem(items, next);
      } else if (homeEnd && event.key === 'Home') {
        event.preventDefault();
        const first = findNextIndex(items, -1, 1);
        focusItem(items, first);
      } else if (homeEnd && event.key === 'End') {
        event.preventDefault();
        const last = findNextIndex(items, items.length, -1);
        focusItem(items, last);
      }
    },
    [enabled, getFocusableItems, orientation, findNextIndex, focusItem, homeEnd],
  );

  const setFocusedIndex = useCallback(
    (index: number) => {
      const items = getFocusableItems();
      if (index >= 0 && index < items.length) {
        focusItem(items, index);
      }
    },
    [getFocusableItems, focusItem],
  );

  return {
    containerProps: { onKeyDown: handleKeyDown },
    focusedIndex,
    setFocusedIndex,
  };
}

/**
 * useRovingFocus Types
 *
 * TypeScript interfaces for the useRovingFocus hook.
 *
 * @packageDocumentation
 */

import type { KeyboardEvent, RefObject } from 'react';

/**
 * Options for the useRovingFocus hook.
 *
 * @example
 * ```tsx
 * const { containerProps } = useRovingFocus({
 *   containerRef: ref,
 *   orientation: 'vertical',
 *   wrap: true,
 *   itemSelector: '[role="option"]',
 *   enabled: true,
 * });
 * ```
 */
export interface UseRovingFocusOptions {
  /**
   * Ref to the container element that holds the focusable items.
   */
  containerRef: RefObject<HTMLElement | null>;

  /**
   * The orientation of the roving focus navigation.
   * Determines which arrow keys are used for navigation.
   * @default 'vertical'
   */
  orientation?: 'vertical' | 'horizontal' | 'both';

  /**
   * Whether focus should wrap around when reaching the boundaries.
   * @default true
   */
  wrap?: boolean;

  /**
   * Whether Home and End keys navigate to first/last items.
   * @default true
   */
  homeEnd?: boolean;

  /**
   * CSS selector used to identify focusable items within the container.
   * @default '[role="option"]'
   */
  itemSelector?: string;

  /**
   * CSS selector used to identify disabled items that should be skipped.
   * @default '[aria-disabled="true"]'
   */
  disabledSelector?: string;

  /**
   * Whether the roving focus behavior is enabled.
   * When false, no keyboard navigation occurs.
   * @default true
   */
  enabled?: boolean;
}

/**
 * Return value of the useRovingFocus hook.
 *
 * @example
 * ```tsx
 * const { containerProps, focusedIndex, setFocusedIndex } = useRovingFocus(options);
 *
 * return (
 *   <ul ref={ref} {...containerProps}>
 *     {items.map((item, i) => (
 *       <li key={i} tabIndex={i === focusedIndex ? 0 : -1}>{item}</li>
 *     ))}
 *   </ul>
 * );
 * ```
 */
export interface UseRovingFocusReturn {
  /**
   * Props to spread onto the container element.
   * Includes the onKeyDown handler for keyboard navigation.
   */
  containerProps: {
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
  };

  /**
   * The index of the currently focused item.
   */
  focusedIndex: number;

  /**
   * Programmatically set the focused item by index.
   * Moves focus and updates tabIndex attributes accordingly.
   */
  setFocusedIndex: (index: number) => void;
}
